import React from 'react'

type Section = { heading: string; paragraphs: string[]; bullets?: string[] }
type Guide = { title: string; dek: string; sections: Section[] }

const guides: Record<string, Guide> = {
  'weekly-budget-calculator': {
    title: 'Weekly Budgeting: A Complete Practical Guide',
    dek: 'A weekly budget is not a smaller monthly budget. It is a cash-flow control system built around the decisions that actually change from Monday to Sunday: food, transport, convenience spending, entertainment, shopping, and short-term saving.',
    sections: [
      { heading: 'Why a weekly budget can reveal problems a monthly budget hides', paragraphs: [
        'Monthly totals are useful for rent, insurance, utilities, and other fixed obligations, but they are slow feedback for day-to-day spending. If you overspend on restaurants, groceries, rides, or shopping during the first ten days of a month, a monthly plan may not make the problem obvious until much of the money is already gone. A weekly plan shortens that feedback loop. You can compare income and controllable spending every seven days, identify the category causing the leak, and adjust the next few days instead of waiting for a new month.',
        'Weekly budgeting is especially useful when income arrives weekly or biweekly. A biweekly paycheck does not divide cleanly into calendar months: two months each year normally contain three biweekly paydays. Treating every month as identical can therefore create false confidence in high-paycheck months and unnecessary stress in ordinary two-paycheck months. A weekly view normalizes the rhythm. You can reserve the weekly equivalent of fixed bills, then decide how much remains for flexible categories and savings.'
      ]},
      { heading: 'Convert monthly obligations before deciding what is safe to spend', paragraphs: [
        'The most common mistake is to treat the full checking-account balance as spendable. Before setting a grocery or entertainment allowance, convert fixed monthly obligations into a weekly reserve. A practical conversion is monthly amount × 12 ÷ 52. A $1,800 rent payment therefore represents about $415.38 per week even though the landlord is paid once a month. A $120 monthly phone plan represents about $27.69 per week. Reserving these amounts mentally or in a separate bills account prevents discretionary spending from consuming money that already has a future job.',
        'Annual and irregular bills need the same treatment. If auto insurance costs $1,200 every six months, the real weekly cost is about $46.15. If holiday gifts typically cost $1,000, setting aside roughly $19.23 per week turns December from an emergency into a planned expense. This is the logic behind sinking funds: predictable but non-monthly expenses are not emergencies. They are future bills that can be converted into small weekly contributions.'
      ]},
      { heading: 'Build category limits from your own baseline, not an idealized budget', paragraphs: [
        'Start with four to eight weeks of actual transactions. Group them into categories that correspond to decisions you can change: groceries, dining, transportation, entertainment, personal care, shopping, health, and subscriptions are common examples. Calculate a weekly average for each category. That average is your baseline, not necessarily your target. If restaurant spending averages $140 per week and you immediately set a $40 limit, the budget may fail because it requires a dramatic lifestyle change. A first target of $100 or $110 may be more sustainable and still free meaningful cash.',
        'Categories should also reflect your household. A commuter with a long drive needs a different transportation allowance from a remote worker. A parent buying food for four people cannot use an individual grocery benchmark without adjustment. Someone with a chronic prescription cost may have a health category that is effectively fixed. The calculator is most useful when the numbers describe your real constraints rather than a generic percentage rule.'
      ]},
      { heading: 'Worked example: turning a paycheck into a weekly plan', paragraphs: [
        'Assume take-home income averages $1,250 per week. Fixed obligations converted to weekly equivalents total $650. You want to save $150 per week, leaving $450 for variable spending. You might initially allocate $150 to groceries, $70 to transportation, $60 to dining and coffee, $45 to entertainment, $35 to personal care, $25 to health items, $45 to shopping, and $20 to subscriptions or app purchases. Those limits add to $450, so every dollar has a role before the week begins.',
        'Suppose Wednesday night the calculator shows $105 of the $150 grocery allowance used, $55 of the $60 dining allowance used, and only $10 spent on entertainment. The correct response is not necessarily to declare the budget a failure. The information tells you where flexibility exists. You can cook at home for the rest of the week, use the unused entertainment allocation if needed, and preserve the $150 savings goal. A budget is a decision tool, not a scorecard that punishes normal variation.'
      ]},
      { heading: 'Handle biweekly pay, five-week months, and uneven income carefully', paragraphs: [
        'For biweekly pay, divide a normal paycheck by two to estimate weekly income, but do not automatically increase recurring spending during the two three-paycheck months. Those extra checks are powerful for annual goals: building an emergency fund, paying insurance premiums, reducing debt principal, funding an IRA, or covering travel. If you permanently raise weekly lifestyle spending because of an occasional third paycheck, the following month can feel artificially tight.',
        'Freelancers, hourly workers, and commission earners should use a conservative income floor. One method is to average the lowest three or four normal months from the past year and convert that figure to a weekly amount. Build essential spending around that floor. When income exceeds the floor, divide the surplus among taxes, business reserves, sinking funds, debt, and long-term saving. This approach reduces the risk of committing to spending that only works during unusually strong weeks.'
      ]},
      { heading: 'Separate a spending problem from a fixed-cost problem', paragraphs: [
        'A weekly deficit does not always mean you buy too much coffee. If fixed housing, debt, insurance, childcare, and transportation commitments consume most take-home pay, cutting small discretionary categories may not close the gap. Use the weekly calculation to quantify the size of the deficit. A $25 weekly shortfall might be solved by subscriptions and dining changes; a $350 weekly shortfall probably requires a structural decision such as refinancing debt, changing housing, increasing income, selling a costly vehicle, or renegotiating a major recurring expense.',
        'This distinction matters because repeated tiny cuts can create budget fatigue while leaving the real problem untouched. Rank expenses by annual impact. Saving $15 per week is $780 per year; reducing a recurring payment by $200 per month is $2,400 per year. Both matter, but the second change has more leverage. Weekly budgeting should help prioritize high-impact decisions, not merely encourage constant deprivation.'
      ]},
      { heading: 'Use surplus intentionally and treat deficits as information', paragraphs: [
        'When the calculator shows a surplus, decide where it goes before the next week begins. A useful sequence is to maintain a small checking buffer, build an emergency reserve, capture any employer retirement match, eliminate expensive revolving debt, fund near-term sinking funds, and invest for longer-term goals. The exact order depends on interest rates, job stability, taxes, and personal priorities, but an unassigned surplus often turns into unplanned spending.',
        'When it shows a deficit, inspect whether the week was abnormal. A medical copay, annual membership, school expense, or car repair can distort one week. If the same category exceeds its limit repeatedly, however, the budget needs a decision: raise the category and reduce something else, or change the behavior creating the overage. A realistic budget that balances is more useful than an aspirational budget that is violated every week.'
      ]},
      { heading: 'A four-week review turns tracking into better decisions', paragraphs: [
        'After four weeks, compare planned and actual amounts by category. Look for patterns rather than isolated mistakes. Groceries may be consistently 12% above target while entertainment is consistently below target. Transportation may spike only during weeks with office travel. Dining may rise on late-work nights. These patterns suggest specific fixes: adjust category limits, batch-cook on predictable busy days, combine errands, cancel unused subscriptions, or move money between categories to reflect reality.',
        'Also compare the calculated savings rate with actual account balances. A plan can show a theoretical surplus that never reaches savings because money is left in checking and later spent. Automating a transfer shortly after payday closes that gap. The strongest weekly budget is one where the calculator, bank transactions, and actual savings contributions tell the same story.'
      ]},
      { heading: 'What this calculator does not decide for you', paragraphs: [
        'The calculator can total categories, show a surplus or deficit, estimate a savings rate, and annualize weekly behavior. It cannot determine whether a particular expense is emotionally worthwhile, whether your emergency fund is large enough for your job risk, or whether paying debt is preferable to investing in your specific tax situation. It also cannot predict weeks with unusual expenses. Use the result as a planning estimate and combine it with account statements, debt terms, benefit information, and your own priorities.',
        'Do not interpret a single strong week as proof that an annual goal is achieved. Vacations, holidays, insurance renewals, school costs, home repairs, and medical expenses make real life lumpy. The purpose of a weekly budget is to create visibility and a repeatable decision process. Consistency over many weeks matters more than perfection in any one week.'
      ]}
    ]
  },
  'savings-rate-calculator': {
    title: 'Savings Rate: How to Measure It and Use It Correctly',
    dek: 'Savings rate looks like one percentage, but the definition of income, the treatment of retirement contributions, debt principal, employer matches, and one-time cash flows can materially change the result. A useful savings rate is one you define consistently and can act on.',
    sections: [
      { heading: 'Choose a definition before comparing your savings rate', paragraphs: [
        'Two people can save the same dollars and report different savings rates because they use different denominators. A take-home savings rate divides savings by after-tax cash income. A gross savings rate divides contributions by gross pay. Some households include employer retirement contributions in both savings and compensation; others exclude them. None of these definitions is automatically wrong. The important rule is consistency. Pick a method that answers your question and use the same method month after month.',
        'For household cash-flow decisions, after-tax income is intuitive because it measures how much of spendable cash you keep. For retirement-plan benchmarking, gross income can be easier because contribution percentages on a 401(k) are stated against gross wages. If you compare your number with an article, survey, or financial guideline, check which definition that source uses before concluding that you are ahead or behind.'
      ]},
      { heading: 'What normally counts as saving', paragraphs: [
        'Common saving includes cash moved to an emergency fund, retirement-plan contributions, IRA deposits, HSA money intended for future medical costs, taxable brokerage contributions, education savings, and cash accumulated for a future goal. Whether extra debt principal counts is a matter of purpose. Paying down principal increases net worth, so a net-worth savings rate may include it. A liquid-investment savings rate may exclude it because home equity or prepaid debt cannot be spent as easily as cash or securities.',
        'Do not count money that merely moves between checking and a savings account if it is routinely transferred back and spent. The economic question is whether current income is being retained for future use or used to reduce a liability. Similarly, unrealized investment gains are investment returns, not current-period saving. Keeping contributions and market performance separate helps you judge behavior without confusing it with a good or bad market month.'
      ]},
      { heading: 'Employer match can be shown two ways', paragraphs: [
        'An employer match is real compensation deposited for your future, so including it can provide a fuller picture of total saving. Suppose take-home pay is $5,000 per month, you contribute $500 to retirement, save $300 in cash, and your employer adds $250. Excluding the match, your cash-based rate is 16%. Including the match only in savings would produce 21%, but that mixes definitions. A cleaner total-compensation method adds the $250 to both savings and income, producing $1,050 saved from $5,250 of measured compensation, or 20%.',
        'For personal behavior tracking, many people prefer to exclude the match so the percentage reflects choices they control. For retirement projections, include the employer contribution because it will actually compound in the account. The calculator result becomes more meaningful when you know which question you are answering.'
      ]},
      { heading: 'Why savings rate has two effects on financial independence', paragraphs: [
        'A higher savings rate does more than increase the amount invested. If income is stable, saving more also means spending less. That reduces the portfolio required to support the same lifestyle. This is why savings rate is so powerful in financial-independence planning. Moving from saving 10% to 30% simultaneously sends more cash into investments and lowers the annual spending level that those investments eventually need to cover.',
        'However, simple FIRE tables are illustrations, not promises. They depend on investment returns, inflation, taxes, withdrawal strategy, retirement length, healthcare costs, pensions, Social Security, and whether current spending resembles future spending. A household with temporarily low expenses because it lives with family should not assume that today’s high savings rate implies the same retirement requirement later.'
      ]},
      { heading: 'Worked example: improving the rate without pretending expenses disappear', paragraphs: [
        'Assume monthly take-home income is $6,000. Retirement contributions taken from the paycheck are already excluded from take-home, so for a clean after-tax cash-flow calculation you decide to add those contributions back to both income and savings. You contribute $600 to retirement, transfer $500 to a brokerage account, and add $300 to an emergency fund. Adjusted income is $6,600 and measured saving is $1,400, giving a rate of about 21.2%.',
        'You want to reach 25%. Instead of cutting every category equally, inspect the annualized gap. At $6,600 of measured monthly income, 25% is $1,650, so the gap is $250 per month. That can be approached with a $100 automatic increase after the next raise, $80 from unused subscriptions and recurring services, and $70 from a realistic dining reduction. The target becomes a specific $250 decision rather than a vague instruction to “save more.”'
      ]},
      { heading: 'Measure the rate over enough time to handle irregular cash flows', paragraphs: [
        'One month can be misleading. Bonuses, tax refunds, annual insurance payments, vacations, tuition, property taxes, and holiday spending create spikes. A rolling three-month or twelve-month savings rate smooths those events. Add all saving during the period and divide by all income using the same definition. Do not simply average monthly percentages when monthly income varies significantly; a dollar-weighted period calculation is more accurate.',
        'Variable-income workers should be particularly careful. A freelancer who earns $12,000 one month and $3,000 the next may show extreme monthly rates even when the annual plan is healthy. Set aside taxes first, define business versus personal income clearly, and evaluate the personal savings rate over a longer window.'
      ]},
      { heading: 'Increasing savings rate: attack recurring decisions before tiny purchases', paragraphs: [
        'The largest improvements often come from recurring structural expenses: housing, vehicles, debt interest, insurance, childcare arrangements, and automatic subscriptions. A $250 monthly reduction in a recurring cost improves annual saving by $3,000 without requiring a fresh decision every day. Small purchases still matter when frequent, but they should not distract from larger fixed commitments.',
        'Income growth can be equally important. If a raise is absorbed entirely by lifestyle inflation, the savings rate barely changes. If part of each raise is automatically directed to retirement or investments, the rate can rise without reducing current nominal spending. A practical rule is to pre-commit a percentage of future raises or bonuses to long-term goals before the higher income becomes part of normal lifestyle expectations.'
      ]},
      { heading: 'Do not maximize the percentage at the expense of resilience', paragraphs: [
        'A very high savings rate is not automatically better if it depends on skipping necessary healthcare, carrying inadequate insurance, neglecting maintenance, or keeping no accessible cash reserve. Retirement accounts can be tax-efficient but may be inconvenient for short-term emergencies. Balance long-term investing with liquidity appropriate to your household risk. Someone with unstable income or a single-income household may reasonably hold more cash than a dual-income household with highly stable employment.',
        'Likewise, saving while carrying very expensive credit-card debt can be inefficient beyond a basic emergency buffer and any employer match. The interest avoided by paying a 20% balance is economically different from the uncertain return on an investment. The calculator measures the rate; it does not replace prioritization among competing uses of cash.'
      ]},
      { heading: 'Use the percentage as a dashboard, not a moral grade', paragraphs: [
        'Savings capacity changes through life. Childcare years, education, relocation, unemployment, caregiving, and medical events can temporarily lower the rate. A percentage that was easy at age 25 may be unrealistic during a high-cost family stage, while later income growth may allow a much higher rate. Compare the number primarily with your own plan and trajectory.',
        'The best use of this calculator is to create a repeatable metric: define income, define saving, calculate it on the same schedule, and connect changes in the percentage to actual goals. If the rate rises but emergency cash, retirement balances, or debt reduction do not improve as expected, reconcile the inputs. A useful financial metric should agree with what is happening on the balance sheet.'
      ]}
    ]
  },
  'qualified-dividend-tax-calculator': {
    title: 'Qualified Dividends and Federal Tax: Detailed Guide',
    dek: 'Qualified dividends can receive preferential federal rates, but the result depends on the security, holding period, taxable income, filing status, other capital gains, and possible surtaxes. The label on a brokerage statement is only one part of the calculation.',
    sections: [
      { heading: 'Qualified and ordinary dividends are different tax categories', paragraphs: [
        'A cash dividend is not automatically taxed at the preferential long-term capital-gain rate. For federal income-tax purposes, a dividend generally needs to be paid by an eligible U.S. corporation or qualifying foreign corporation and satisfy holding-period requirements to be treated as qualified. Dividends that do not meet those conditions are generally included with ordinary income. This distinction can materially change federal tax because ordinary-income brackets and long-term capital-gain brackets use different rate schedules.',
        'Brokerage Form 1099-DIV typically reports total ordinary dividends and the portion that is qualified. The qualified amount is generally included inside the ordinary-dividend total rather than being an additional amount. When estimating tax, avoid adding the two boxes together as though they were separate income streams. Use tax documents and current IRS instructions for the filing year when preparing an actual return.'
      ]},
      { heading: 'The holding-period rule is more important than many investors expect', paragraphs: [
        'For common stock, qualification generally depends on holding the shares for more than 60 days during a specified 121-day window surrounding the ex-dividend date. Preferred stock can use a different period when the dividend relates to a longer accrual period. Days when your risk of loss is diminished through certain hedges or arrangements may not count in the normal way. This means buying a stock shortly before its ex-dividend date simply to capture a dividend can produce a different tax result from holding it as a longer-term investment.',
        'Lot-level tracking matters when you purchase the same stock on different dates. Some lots may satisfy the holding requirement while newer lots do not. Reinvested dividends also purchase new shares with their own holding periods. A calculator can estimate tax from amounts you classify as qualified, but your broker records and tax forms determine how much actually receives that treatment.'
      ]},
      { heading: 'Preferential rates are stacked on top of other taxable income', paragraphs: [
        'Qualified dividends do not exist in a separate universe. The applicable federal rate depends on taxable income after deductions and on how ordinary income and preferential-rate income stack within the tax calculation. A taxpayer can therefore have some qualified dividends taxed at one preferential rate and the remainder at a higher rate when the income crosses a threshold. Applying a single headline rate to the entire dividend amount can overstate or understate tax near a bracket boundary.',
        'Other long-term capital gains use the same preferential-rate framework and can push qualified dividends into a higher band. Conversely, capital losses may affect the overall return. The calculator should be viewed as an estimate based on the income information entered, not as a substitute for the qualified-dividends-and-capital-gain tax worksheet or tax software that incorporates the full return.'
      ]},
      { heading: 'Worked example: why the same dividend can produce different tax', paragraphs: [
        'Imagine two single investors each receive $10,000 of dividends from the same eligible corporation and both satisfy the holding period. Investor A has relatively modest taxable ordinary income; Investor B has much higher salary and investment income. Even though the security and dividend are identical, the federal tax attributable to the qualified dividend can differ because their taxable-income positions differ. Investor B may also face additional taxes that Investor A does not.',
        'Now change the facts: Investor A bought half the shares only a few days before the ex-dividend date and sells them shortly afterward. If that portion fails the holding requirement, only the dividend associated with qualifying shares may receive preferential treatment. This illustrates why “dividend amount × 15%” is not a universal formula.'
      ]},
      { heading: 'REITs, money-market distributions, and other payments need separate attention', paragraphs: [
        'Investors often assume every distribution shown as a dividend in an app is qualified. Real-estate investment trust distributions are commonly not qualified dividends, although tax law may provide other deductions or character categories for portions of the distribution. Money-market fund distributions are generally interest-like ordinary dividends. Mutual funds and ETFs can distribute qualified dividends, nonqualified dividends, capital-gain distributions, and return of capital in the same year.',
        'Return of capital is particularly different: it generally reduces basis rather than being immediately taxed as a dividend until basis rules cause another result. A fund’s year-end tax statement can therefore differ from the cash labels shown during the year. For tax planning, use estimated classifications cautiously and reconcile them to the final Form 1099-DIV.'
      ]},
      { heading: 'Do not forget the Net Investment Income Tax and state taxes', paragraphs: [
        'High-income taxpayers may owe the 3.8% Net Investment Income Tax on some or all net investment income when modified adjusted gross income exceeds the applicable threshold. Qualified dividends can be part of net investment income. The surtax is separate from the preferential capital-gain rate, so a taxpayer’s effective federal burden can be higher than the headline qualified-dividend percentage.',
        'State treatment also varies. Some states tax dividends as ordinary income even when federal law provides a preferential rate; states without an individual income tax may impose no comparable state tax. A federal-only calculator should therefore not be interpreted as total tax liability. Residency, sourcing, municipal rules, and state-specific deductions can matter.'
      ]},
      { heading: 'Dividend tax planning should not override investment quality', paragraphs: [
        'Preferential taxation can improve after-tax return, but tax status alone does not make a stock attractive. A company can reduce or eliminate its dividend, its share price can fall, and a high yield can reflect business distress. Investors should evaluate total return, diversification, valuation, balance-sheet quality, and portfolio fit rather than buying solely because a payment may qualify for a lower tax rate.',
        'Tax-efficient account location can also matter. Holding income-producing assets in retirement accounts can defer or change current taxation, but withdrawals from traditional accounts have their own rules and Roth accounts have different treatment. The optimal location depends on expected returns, turnover, tax brackets, account access, and estate goals—not simply whether a dividend is qualified today.'
      ]},
      { heading: 'Use the calculator for scenarios, then verify with filing-year rules', paragraphs: [
        'A useful scenario is to compare the estimated federal tax if the same dividend is qualified versus ordinary. The difference approximates the value of preferential treatment under the entered assumptions. You can also vary other taxable income to see whether a bonus, Roth conversion, asset sale, or additional gain could change the marginal treatment of the dividend.',
        'Tax thresholds, deductions, and other rules can change by year. Brokerage classifications can also be corrected after year-end. For an actual tax return, rely on current IRS forms, instructions, tax software, or a qualified tax professional. This calculator is strongest as an educational and planning tool rather than a final tax-return computation.'
      ]},
      { heading: 'Records that make dividend tax estimates more reliable', paragraphs: [
        'Keep purchase dates, sale dates, reinvestment records, corporate-action notices, and year-end Forms 1099-DIV. If shares move between brokers, verify that cost basis and acquisition dates transfer correctly. For foreign corporations, additional eligibility questions may apply. For options or hedged positions, holding-period rules can become more complex than a simple calendar-day count.',
        'When comparing tax scenarios, document whether the calculator input represents gross dividends, qualified dividends only, or total ordinary dividends. Consistent labeling prevents double counting. Good records turn the calculator from a rough percentage exercise into a useful planning model that can be reconciled to the tax documents you eventually receive.'
      ]}
    ]
  },
  'margin-trading-calculator': {
    title: 'Margin Trading: Leverage, Equity, Interest, and Liquidation Risk',
    dek: 'Margin magnifies both gains and losses. A useful margin calculation must track borrowed funds, account equity, maintenance requirements, interest cost, and the price at which a broker may require more collateral or liquidate positions.',
    sections: [
      { heading: 'Understand the balance sheet of a margin position', paragraphs: [
        'A margin purchase has three moving pieces: the market value of securities, the amount borrowed from the broker, and your equity. If you buy $20,000 of stock using $10,000 of cash and $10,000 of margin debt, account equity starts at $10,000. If the stock rises to $24,000 while the debt remains roughly $10,000 before interest, equity becomes $14,000. A 20% increase in the asset produced a 40% increase in equity before financing costs. The same leverage works in reverse.',
        'If the stock falls to $16,000, equity becomes $6,000—a 40% decline in your equity from a 20% decline in the asset. This nonlinear experience is why leveraged portfolios can become difficult to recover after losses. A 50% loss requires a 100% gain just to return to the starting amount, and margin interest continues to accrue while you wait.'
      ]},
      { heading: 'Initial margin and maintenance margin answer different questions', paragraphs: [
        'Initial margin governs how much equity is generally required when opening or increasing a position. Maintenance margin governs the minimum equity that must remain afterward. Brokers can impose house requirements that are stricter than regulatory minimums, and those requirements can vary by security, concentration, volatility, liquidity, or market conditions. A position that was permitted when opened can therefore become subject to a higher requirement later.',
        'The key maintenance ratio is equity divided by current market value. As prices fall, market value and equity decline while the loan balance does not fall automatically. Once the ratio breaches the broker’s requirement, the account may face a margin call or liquidation. Do not assume you will always receive time to deposit cash before positions are sold; brokerage agreements often provide broad liquidation rights.'
      ]},
      { heading: 'Derive the approximate margin-call price', paragraphs: [
        'For a simple long position with a fixed loan balance, you can estimate the market value at which equity equals the maintenance requirement. If L is the margin loan and m is the maintenance percentage, required market value is approximately L ÷ (1 − m). If the loan is $10,000 and maintenance is 30%, the critical market value is about $14,285.71. At that value, equity is about $4,285.71, which is 30% of market value.',
        'To convert that market value to a per-share price, divide by the number of shares. Real accounts can be more complicated because interest increases the debit balance, multiple positions offset or concentrate risk, options have special requirements, and the broker may change house margin. Treat the result as a planning threshold, not a guarantee of when liquidation will occur.'
      ]},
      { heading: 'Interest changes the break-even return', paragraphs: [
        'Borrowed money has a carrying cost. If you borrow $25,000 at an annual margin rate of 10% for six months, a simple estimate of interest is about $1,250 before compounding and rate changes. Your securities must earn enough to cover that financing cost before leverage improves the result. Dividends can offset some cost, but dividends are not guaranteed and may create taxes in a taxable account.',
        'Margin rates are often tiered by debit balance and can change with benchmark rates or broker policy. For a position held for days, interest may be modest; for a position held for years, financing can consume a large part of expected return. Compare leveraged return after interest, taxes, and trading costs with the unleveraged alternative rather than focusing only on gross percentage gains.'
      ]},
      { heading: 'Worked example: a gain, a loss, and the effect of financing', paragraphs: [
        'Suppose you contribute $15,000 and borrow $15,000 to buy $30,000 of stock. If the position rises 15% to $34,500, equity before interest is $19,500. The asset gained $4,500, which is a 30% gross gain on your original $15,000 equity. If six months of margin interest costs $750, equity attributable to the trade falls to $18,750, making the gain 25% before taxes and other costs.',
        'If instead the stock falls 15% to $25,500, equity before interest is $10,500. After $750 of interest, it is $9,750—a 35% decline from the original equity even though the security fell only 15%. This asymmetry is the practical meaning of leverage: the loan is a fixed claim while your equity absorbs market movement and financing cost.'
      ]},
      { heading: 'Concentration makes margin risk more dangerous', paragraphs: [
        'A diversified portfolio can still fall sharply, but a concentrated position can gap downward on company-specific news before you can respond. Earnings surprises, regulatory actions, failed trials, fraud allegations, financing problems, or acquisition news can move a single stock far more than a broad index. If the account is highly leveraged, an overnight gap can move directly through the theoretical call price.',
        'Brokers may also raise maintenance requirements on volatile or concentrated securities. A position that requires 30% maintenance today might require substantially more under a house rule tomorrow. That can create a margin deficiency even without a large price change. Stress-test both price declines and requirement increases rather than assuming one fixed maintenance percentage.'
      ]},
      { heading: 'Short selling and options require different margin logic', paragraphs: [
        'This long-margin calculator should not be applied mechanically to short sales. In a short position, losses grow as the security rises and are theoretically unlimited because a stock price has no fixed upper bound. Borrow fees, hard-to-borrow charges, dividend obligations, and changing requirements can materially affect the result. Options, futures, portfolio margin, and leveraged ETFs also have risk structures that differ from a simple stock purchase financed with a margin loan.',
        'If your account contains several instrument types, the broker’s actual margin engine is the authoritative source for buying power and requirements. Use a simple calculator to understand leverage concepts and scenario sensitivity, then compare the estimate with the brokerage platform before placing a trade.'
      ]},
      { heading: 'Risk controls are more important than the maximum buying power', paragraphs: [
        'The maximum amount a broker allows you to borrow is not necessarily a prudent amount to borrow. Consider maintaining a substantial equity cushion above maintenance, limiting leverage on volatile assets, keeping cash outside the margin account for unrelated emergencies, and deciding in advance what price or thesis change will cause you to reduce the position. Relying on a margin call as the risk-management plan gives control of timing to the broker.',
        'Also consider correlation. Ten technology stocks may look diversified by ticker but can decline together when interest-rate expectations or sector sentiment changes. Margin risk should be evaluated at the portfolio level: what happens if several positions fall simultaneously and requirements rise at the same time?' 
      ]},
      { heading: 'What to read in your brokerage agreement', paragraphs: [
        'Before using margin, review the broker’s interest schedule, how rates are calculated, maintenance requirements, concentration rules, liquidation policy, and whether the firm can sell securities without contacting you first. Understand which assets are marginable and how unsettled trades or withdrawals affect buying power. These details can differ across firms and account types.',
        'The calculator can show how leverage behaves under entered assumptions, but it cannot predict broker discretion, intraday price gaps, liquidity, tax consequences, or future interest rates. Margin is a financing tool with the potential for losses exceeding the cash initially committed. Use scenario analysis conservatively and verify live requirements with your broker.'
      ]}
    ]
  },
  'rental-property-depreciation-calculator': {
    title: 'Rental Property Depreciation: Basis, Allocation, and Tax Planning Guide',
    dek: 'Rental real estate depreciation is a tax allocation of qualifying property cost over a recovery period. The difficult part is usually not the division—it is determining depreciable basis, separating land, handling improvements, tracking placed-in-service dates, and understanding what happens when the property is sold.',
    sections: [
      { heading: 'Depreciation starts with basis, not the purchase price alone', paragraphs: [
        'A rental-property purchase price often includes land and building together, but land is not depreciable because it is not considered to wear out in the same manner as a building. You therefore need a reasonable allocation between land and depreciable improvements. Closing documents, property-tax assessments, appraisals, and other support can inform the allocation. The defensibility of that split matters because assigning more value to the building generally increases depreciation deductions.',
        'Basis can also include certain acquisition costs and later capital improvements, while some settlement charges are currently deductible or treated differently. The exact treatment depends on the nature of each cost. Keep the closing disclosure, purchase agreement, invoices, and allocation support rather than relying on a single number entered into a calculator years later.'
      ]},
      { heading: 'Placed in service is different from purchase date', paragraphs: [
        'Depreciation generally begins when the property is placed in service for rental use—meaning it is ready and available to rent—not simply when you sign the purchase contract. If you buy a house in March, renovate it for several months, and make it available to tenants in July, July may be the relevant placed-in-service period. This distinction affects the first-year deduction.',
        'Residential rental buildings in the United States are generally depreciated under MACRS using a 27.5-year recovery period and the mid-month convention, subject to current tax rules. The convention means first- and last-year depreciation is prorated rather than simply taking a full annual amount based on the number of days owned. Tax software or official tables are normally used for return preparation.'
      ]},
      { heading: 'Building, appliances, furniture, and improvements may have different lives', paragraphs: [
        'Not every asset associated with a rental property follows the building’s recovery period. Appliances, carpeting, furniture, fencing, landscaping improvements, and certain equipment can fall into different asset classes and recovery periods depending on facts and current law. A major addition to the building may be capitalized separately. Repairs that merely keep the property in ordinary operating condition can have different treatment from improvements that better, restore, or adapt the property.',
        'This classification is one reason a single “purchase price ÷ 27.5” calculation can be incomplete. The calculator is useful for estimating building depreciation, but owners should maintain an asset schedule that records each significant capitalized item, its cost, date placed in service, recovery method, and accumulated depreciation.'
      ]},
      { heading: 'Worked example: allocating land and estimating annual building depreciation', paragraphs: [
        'Assume a rental is acquired for $400,000 and a supportable allocation assigns $80,000 to land and $320,000 to the building before considering other basis adjustments. Ignoring first-year convention effects for illustration, straight-line annual building depreciation over 27.5 years is approximately $11,636.36. That deduction is noncash: you do not write an $11,636 check each year, but taxable rental income may be reduced by the allowable depreciation expense.',
        'Now suppose you later install a qualifying $12,000 appliance package and complete a $30,000 capital improvement. Those expenditures should not automatically be blended into the original building calculation without classification. Each may require its own depreciation treatment and placed-in-service date. Accurate schedules become increasingly valuable as a property is held for many years.'
      ]},
      { heading: 'Depreciation can create a tax loss while the property produces cash', paragraphs: [
        'Rental cash flow and taxable rental income are different measures. A property might collect $36,000 of rent and pay $24,000 of cash operating expenses and interest, leaving $12,000 before principal payments and capital expenditures. If allowable depreciation is $11,600, taxable rental income before other adjustments may be much smaller than cash generated. This tax shelter effect is one reason depreciation is important to real-estate investors.',
        'But a paper tax loss is not automatically deductible against salary or other active income. Passive-activity rules, participation level, income thresholds, real-estate-professional rules, at-risk limits, and other provisions can restrict current use of losses. Suspended losses may carry forward. A depreciation calculator estimates one deduction; it does not determine whether that deduction reduces your current-year tax bill.'
      ]},
      { heading: 'Mortgage principal is not a depreciation deduction', paragraphs: [
        'Investors sometimes confuse loan payments with deductible expenses. The interest portion of a qualifying rental mortgage can generally be an expense, subject to applicable rules, but repayment of principal reduces the liability and builds equity; it is not normally a current deduction. Depreciation is based on qualifying property basis, not on how much of the purchase was financed.',
        'This means two owners who buy identical properties at the same basis but use different down payments can have similar building depreciation even though their cash flow differs substantially. Financing affects interest expense, leverage, risk, and return on equity, while depreciation follows the tax basis of depreciable assets.'
      ]},
      { heading: 'Sale of the property brings prior depreciation back into the conversation', paragraphs: [
        'Depreciation reduces adjusted basis over time. When the property is sold, gain is generally measured using adjusted basis rather than the original unadjusted purchase basis. Depreciation-related gain can be subject to special federal tax treatment often described as unrecaptured Section 1250 gain, and other assets can have separate recapture rules. The tax effect of selling a long-held rental can therefore be very different from simply applying a capital-gains percentage to sale price minus purchase price.',
        'Importantly, tax rules can account for depreciation that was allowable even if an owner failed to claim it. Skipping depreciation does not necessarily avoid future basis reduction. If prior returns omitted material depreciation, professional advice may be needed to determine the appropriate correction procedure rather than improvising on the current return.'
      ]},
      { heading: 'Cost segregation can accelerate deductions but changes complexity', paragraphs: [
        'A cost-segregation study identifies components of a building that may qualify for shorter recovery periods than the main structure. Accelerating deductions can improve near-term cash flow by deferring tax, particularly for larger properties or taxpayers who can currently use the deductions. However, the benefit depends on tax rates, passive-loss limitations, holding period, financing, study cost, and rules governing bonus depreciation or other accelerated methods for the relevant year.',
        'Accelerated depreciation is generally a timing strategy, not free money. Earlier deductions reduce basis faster and can affect taxes on disposition. Model the present value of tax savings and the expected exit rather than judging a strategy solely by the size of the first-year deduction.'
      ]},
      { heading: 'Records and assumptions to verify before using the result', paragraphs: [
        'Keep documents supporting original cost, land allocation, capital improvements, casualty adjustments, insurance reimbursements, prior depreciation, and dates assets were ready for rental use. Reconcile the calculator’s basis with the fixed-asset schedule on the tax return. If the property changed from personal to rental use, basis rules can be more complicated than a normal investment purchase and may involve fair-market-value considerations.',
        'Tax law changes over time and state depreciation may differ from federal treatment. Use this calculator to understand the mechanics and estimate scenarios, then verify filing-year rules with IRS guidance, tax software, or a qualified tax professional. The more years you own a property, the more valuable a clean depreciation schedule becomes for both annual returns and the eventual sale.'
      ]}
    ]
  },

  'loan-comparison-calculator': {
    title: 'How to Compare Loans Beyond the Advertised Monthly Payment',
    dek: 'Two loans for the same amount can produce very different costs because rate, term, fees, timing, prepayment rules, and cash-flow pressure interact. A useful comparison therefore asks not only which payment is lowest, but which offer has the best economic fit for the period you realistically expect to keep the debt.',
    sections: [
      { heading: 'Start by making every offer comparable', paragraphs: [
        'A loan comparison is only meaningful when the inputs describe the same borrowing need. Use the same principal amount and, when possible, the same payoff horizon. If one lender quotes a $25,000 loan for 48 months and another quotes $25,000 for 72 months, the second payment will naturally look smaller even when its rate is worse. Record the amount actually deposited to you as well as the face amount of the note, because an origination fee deducted from proceeds can mean you receive less cash than you are contractually required to repay.',
        'Create a simple offer sheet for each lender: amount financed, nominal interest rate, APR, term, required payment, origination or closing fees, optional products, prepayment terms, and whether the rate is fixed or variable. Keep promotional discounts separate. An autopay discount that disappears when you change banks is not identical to a permanently lower contract rate. Standardizing the facts prevents sales language from controlling the decision.'
      ]},
      { heading: 'Interest rate, APR, and total dollars answer different questions', paragraphs: [
        'The interest rate drives the finance charge applied to the outstanding balance. APR attempts to express certain financing costs as an annualized percentage and is useful for comparing offers with different lender fees. Total interest shows the dollars paid for borrowing if the scheduled payment pattern is followed. Total cost goes one step further by combining principal, interest, and relevant fees. None of these measures should automatically replace the others because each highlights a different dimension of the contract.',
        'Suppose Offer A has a slightly lower rate but charges a large origination fee, while Offer B has no fee and a modestly higher rate. If you keep both loans to maturity, the lower-rate loan may eventually recover its upfront disadvantage. If you expect to refinance or repay after twelve months, it may never reach that break-even point. That is why APR is valuable but a holding-period calculation can be even more informative for borrowers who do not expect to keep the loan for its full stated term.'
      ]},
      { heading: 'Why the lowest payment can be the most expensive offer', paragraphs: [
        'Extending a term spreads principal over more payments, which lowers the required amount each month. The tradeoff is that the balance remains outstanding longer and interest has more time to accumulate. A borrower choosing between four, five, and six years should therefore compare both monthly affordability and lifetime cost. The longer option may be appropriate when cash flow is genuinely constrained, but the smaller payment should not be mistaken for a lender giving a better price.',
        'Term length also affects flexibility later. Long loans can leave a vehicle borrower owing more than the car is worth, or leave a personal-loan borrower carrying old debt while new expenses arrive. If you choose a longer term for safety, check whether extra principal can be paid without penalty. A flexible contract can allow you to make the lower required payment during difficult months while voluntarily following a faster payoff schedule during normal months.'
      ]},
      { heading: 'Worked comparison: fee versus no-fee financing', paragraphs: [
        'Imagine you need $30,000. Lender A offers 7.25% for five years with a 3% origination fee; Lender B offers 7.75% for five years with no origination fee. The headline rate favors A, but a 3% fee is $900. If the fee is withheld from proceeds, borrowing $30,000 may deliver only $29,100, which can force you to borrow more to meet the original need. If the fee is financed, it increases the balance on which interest is effectively paid.',
        'Run both offers through the calculator using the exact contractual treatment of the fee. Then compare required payment, total scheduled interest, total lender cost, and the cost after the period you expect to keep the loan. If you plan to pay the debt off in eighteen months, calculate the remaining balance at that point and add all payments and upfront fees already paid. That shorter-horizon comparison can reverse the ranking produced by a maturity-only calculation.'
      ]},
      { heading: 'Fixed and variable rates require different stress tests', paragraphs: [
        'A fixed-rate loan gives you a known rate for the agreed period, so the primary uncertainties are your own cash flow and whether you refinance or prepay. A variable-rate loan introduces another moving part. The starting rate may be attractive, but the index and contractual margin determine future resets. Read the adjustment frequency, periodic cap, lifetime cap, and any introductory period before treating the initial payment as representative.',
        'For a variable offer, calculate at least a base case and a higher-rate case. Ask what the payment and total cost would look like if the rate rose two or three percentage points, subject to the contract limits. If that stressed payment would be difficult to absorb, the apparent savings at the introductory rate may not compensate for the risk. Comparing a fixed loan with a variable loan is partly a comparison of certainty, not merely today’s percentage.'
      ]},
      { heading: 'Fees, add-ons, and prepayment terms can change the winner', paragraphs: [
        'Look beyond the origination fee. Depending on the loan, there may be application charges, documentation fees, broker compensation, closing costs, points, credit insurance, service contracts, or other financed products. Some costs may be optional and some may not be included in the APR in the way you expect. Ask for a written itemization and distinguish costs required to obtain the credit from products you can decline.',
        'Prepayment language matters if your income is irregular or you expect a bonus, asset sale, refinance, or early payoff. A loan that permits principal-only payments without penalty gives you more control over interest. Confirm how extra payments are applied: reducing principal immediately is different from merely advancing the next due date. If there is a prepayment penalty, model it at the likely payoff date rather than assuming the maturity schedule is your only scenario.'
      ]},
      { heading: 'Use cash-flow margin as a risk measure', paragraphs: [
        'A mathematically cheaper loan can still be a poor choice if its required payment leaves no room for ordinary surprises. Compare the payment with stable monthly take-home income after housing, utilities, insurance, food, transportation, minimum debt payments, and essential saving. The amount left after these obligations is your payment margin. A loan consuming nearly all of that margin increases the chance that a repair, medical bill, or temporary income reduction turns into new revolving debt.',
        'Do not use the lender’s approval amount as evidence of affordability. Underwriting rules answer whether the lender is willing to extend credit under its criteria; they do not know every household goal or future expense. A borrower saving for parental leave, a home purchase, or self-employment transition may rationally choose a smaller loan even when approved for more. Comparison should optimize your financial plan, not maximize the amount available.'
      ]},
      { heading: 'Credit shopping and refinancing deserve their own analysis', paragraphs: [
        'When rate-shopping, obtain quotes close together and compare the same credit profile and loan structure. A prequalification based on a soft inquiry may not be the final price. The binding or final offer can change after verification of income, collateral, debt, or credit. Keep screenshots or disclosures with dates so that an attractive promotional quote is not accidentally compared with a final contract from another lender.',
        'For refinancing, the new loan must be compared with the cost of keeping the existing debt from today forward, not with interest already paid. Past interest is a sunk cost. Calculate the current payoff balance, new fees, new payment, and interest over your expected remaining ownership period. Extending the term can create a lower payment while increasing the time in debt, so compare a refinance using both the proposed term and a payment that preserves the old payoff date.'
      ]},
      { heading: 'A practical decision rule after using the calculator', paragraphs: [
        'First eliminate offers with unacceptable features: unaffordable stressed payments, unclear fees, prepayment restrictions that conflict with your plan, or variable-rate exposure you cannot tolerate. Among the remaining offers, compare total cost over the period you realistically expect to keep the debt. Then check whether the required payment leaves adequate monthly margin. This sequence prevents a tiny rate difference from distracting you from a materially riskier contract.',
        'Finally, verify every calculator input against the lender’s disclosure before signing. Calculators generally assume scheduled payments occur on time and that the entered rate and fees remain as specified. They cannot capture every contract provision, tax consequence, insurance product, or servicing practice. Use the result to organize questions and compare economics, then rely on the actual loan documents for the legal terms.'
      ]},
    ],
  },
  'biweekly-mortgage-calculator': {
    title: 'Biweekly Mortgage Payments: What Actually Creates the Savings',
    dek: 'The power of a true biweekly plan comes from payment frequency: 26 half-payments equal 13 full monthly payments each year. The extra annual principal can shorten amortization, but lender processing rules, escrow, fees, and the timing of each credit determine whether a particular program delivers the result you expect.',
    sections: [
      { heading: 'The calendar creates the extra payment', paragraphs: [
        'A monthly mortgage has twelve scheduled payments per year. A true every-two-weeks schedule has twenty-six half-payments because a 52-week year contains twenty-six two-week periods. Twenty-six halves equal thirteen full monthly payments. That thirteenth payment is the main engine of the accelerated payoff; simply splitting twelve monthly payments into two pieces without making the equivalent of an extra annual payment does not create the same benefit.',
        'This distinction matters because the phrase biweekly is sometimes used loosely. A lender or third-party service may collect half a payment every two weeks but hold the money until a full monthly payment is available. Other systems credit principal more frequently. Before paying a setup or transaction fee, ask exactly when funds are applied, how escrow is handled, and whether twenty-six withdrawals truly produce an additional principal reduction each year.'
      ]},
      { heading: 'Why early principal reduction cuts future interest', paragraphs: [
        'On a standard amortizing fixed-rate mortgage, each scheduled payment contains interest on the outstanding balance plus principal. Early in a long loan, the balance is large, so the interest portion is also large. Extra principal reduces the balance used for later interest calculations. The benefit then compounds through the remaining schedule because every subsequent period begins from a slightly smaller balance.',
        'The effect is strongest when extra payments begin early and the mortgage still has many years remaining. An extra payment made near the end of a loan has less time to prevent future interest. This does not mean late prepayment is useless; it means the calculator should use your current balance, rate, and remaining term rather than quoting a generic savings figure based on a brand-new thirty-year mortgage.'
      ]},
      { heading: 'True biweekly versus one extra payment per year', paragraphs: [
        'You can often reproduce most of the economic effect without enrolling in a formal biweekly service. One method is to make the normal monthly payment and send one additional full principal payment each year. Another is to divide the regular principal-and-interest payment by twelve and add that amount as extra principal to each monthly payment. Over a year, those twelve additions equal one extra monthly payment.',
        'The exact timing creates small differences. Sending extra principal every month reduces the balance sooner than waiting until December to make one large extra payment, so it can save slightly more interest. But convenience matters. A method you can automate and sustain for years is usually better than a theoretically optimal schedule you frequently skip. Use the calculator to compare equivalent annual extra amounts and decide which cash-flow pattern fits your pay cycle.'
      ]},
      { heading: 'Do not accidentally include escrow in the extra-payment math', paragraphs: [
        'A mortgage statement may combine principal, interest, property taxes, homeowners insurance, mortgage insurance, and other escrow items into one monthly amount. Only principal reduction accelerates the loan. If you divide the entire PITI payment in half and assume every extra dollar reduces the balance, the estimate can overstate savings. Base the acceleration calculation on the principal-and-interest obligation and separately continue whatever escrow amount the servicer requires.',
        'Escrow can also change from year to year as taxes and insurance premiums change. That may make the total withdrawal rise even though the mortgage rate is fixed. When comparing monthly and biweekly strategies, hold the loan terms constant and avoid treating an escrow increase as additional loan interest. Your servicer’s annual escrow analysis is separate from the amortization schedule.'
      ]},
      { heading: 'Worked example: evaluating the tradeoff', paragraphs: [
        'Assume a homeowner has a substantial remaining balance on a thirty-year fixed mortgage and enough cash flow to make the equivalent of one extra principal-and-interest payment annually. The calculator can estimate a new payoff date and interest savings by applying that extra amount throughout the schedule. The result should be compared with the baseline schedule from today, not with the original loan if several years have already passed.',
        'Next test a less aggressive plan, such as adding half of the annual extra amount. The difference shows the marginal value of the additional cash. This is useful when the homeowner also has credit-card debt, an underfunded emergency reserve, or retirement matching available. Mortgage prepayment produces a return roughly related to the avoided mortgage interest, but the best use of cash depends on taxes, liquidity, competing debt rates, and investment opportunities.'
      ]},
      { heading: 'Confirm how your servicer applies extra money', paragraphs: [
        'Labeling matters. Some servicing systems may treat an extra amount as an early installment or place it in suspense until enough money exists for a contractual payment. Your goal in an acceleration strategy is generally to have the additional amount applied to principal according to the loan terms. Review the next statement after your first extra payment and confirm that the principal balance declined as expected.',
        'Also check for minimum-payment rules, partial-payment policies, and any prepayment restriction in the note. Most modern residential mortgages allow additional principal, but the contract controls. If a third-party biweekly company charges enrollment or transaction fees, calculate how long the interest savings take to recover those fees. A free principal-only method through the servicer may accomplish the same objective.'
      ]},
      { heading: 'Liquidity is the main cost of aggressive prepayment', paragraphs: [
        'Once cash is used to reduce mortgage principal, accessing it again may require selling the property, obtaining a home-equity product, or refinancing. Those options can take time, depend on credit and property value, and involve fees. Therefore, a homeowner with little emergency cash should not evaluate prepayment solely by the interest saved. A liquid reserve can prevent expensive credit-card borrowing when an appliance fails or income is interrupted.',
        'A balanced approach is to establish emergency reserves and handle higher-cost debt before committing every spare dollar to the mortgage. Homeowners should also consider employer retirement matches and near-term obligations. The calculator quantifies one benefit—avoided mortgage interest—but cannot price the personal value of liquidity or the tax and investment alternatives available to a specific household.'
      ]},
      { heading: 'Refinancing can change the biweekly decision', paragraphs: [
        'If you may refinance soon, the savings from an accelerated schedule should be measured only until the expected refinance date. Extra principal is not lost when you refinance; it lowers the payoff balance. However, the long-term interest savings shown by a calculator assuming you keep the existing mortgage for decades may not describe your actual path. Run a scenario using the expected holding period and compare the lower future balance with other uses of the cash.',
        'After refinancing, avoid resetting the debt horizon without noticing. A homeowner ten years into a thirty-year mortgage who refinances into a new thirty-year term may lower the rate and payment but extend the payoff date. One strategy is to calculate the payment required to keep the original payoff date, then decide whether biweekly or monthly extra principal still makes sense under the new rate.'
      ]},
      { heading: 'When a biweekly strategy is most useful', paragraphs: [
        'The strategy fits borrowers with stable income, adequate reserves, no more urgent high-rate debt, and a desire for a simple forced-prepayment routine. It can be especially natural for households paid every two weeks because the withdrawal aligns with payroll and the two three-paycheck months fund the equivalent extra annual payment. The psychological advantage is automation: the faster payoff happens without requiring a large year-end decision.',
        'It is less compelling when cash flow is volatile, the mortgage rate is very low relative to other priorities, or the program charges avoidable fees. Use the calculator as a scenario tool rather than a promise. Verify the current balance, rate, remaining term, and principal-and-interest payment from your statement, then confirm the servicer’s processing rules before changing your payment schedule.'
      ]},
    ],
  },
  'invoice-calculator': {
    title: 'Building an Invoice That Calculates Correctly and Gets Paid',
    dek: 'An invoice is both arithmetic and communication. The total must correctly handle quantities, rates, discounts, tax, deposits, credits, and late charges, while the document must also tell the customer exactly what was delivered, when payment is due, and how to resolve a dispute.',
    sections: [
      { heading: 'Build the subtotal from auditable line items', paragraphs: [
        'Start with line items that another person can understand without calling you. Each row should identify the product or service, quantity or units, unit price, and extended amount. For time-based work, that might be hours multiplied by an hourly rate; for products, units multiplied by price; for milestones, it may be a fixed project amount. Clear descriptions reduce disputes and make bookkeeping easier for both seller and customer.',
        'The subtotal is the sum before invoice-level discounts, taxes, credits, and other adjustments. Avoid hiding several unrelated services inside one unexplained amount when the contract priced them separately. If a customer questions the bill, a transparent subtotal lets you trace the total back to the agreement, purchase order, time record, or delivery receipt. That audit trail becomes increasingly important as invoices grow in value.'
      ]},
      { heading: 'Decide whether discounts apply before or after tax', paragraphs: [
        'A percentage discount sounds simple, but tax rules can make the order of operations important. A commercial discount that reduces the selling price may reduce the taxable base in some circumstances, while manufacturer coupons, rebates, or other arrangements can be treated differently. The calculator can perform the arithmetic you specify, but the applicable state and local rules determine which amount is legally taxable.',
        'For a straightforward business discount, document the original subtotal, discount rate or dollar amount, discounted subtotal, taxable amount, tax, and final total. If you offer an early-payment discount such as 2/10 net 30, distinguish it from a discount already earned at invoicing. Your accounting system needs to know whether the reduction is part of the sale price or contingent on the customer paying within the stated period.'
      ]},
      { heading: 'Sales tax depends on what, where, and to whom you sell', paragraphs: [
        'There is no single U.S. invoice tax rate. Taxability can depend on the seller’s nexus, customer location, type of product or service, delivery method, exemptions, and local jurisdiction. Physical goods are commonly taxable, but services, software, digital products, shipping, and mixed transactions vary significantly by state. A calculator should therefore accept the rate you have determined rather than pretending one national percentage applies.',
        'Keep exemption certificates and resale documentation when relevant. If an invoice contains both taxable and nontaxable lines, calculate tax only on the appropriate base instead of applying a blanket rate to the entire subtotal. Businesses operating across states may need specialized tax software or professional advice because sourcing and registration obligations can become more complex than the invoice arithmetic itself.'
      ]},
      { heading: 'Deposits, retainers, and credits should not disappear from the history', paragraphs: [
        'If a client paid a deposit before the final invoice, show the full value of the work and then show the deposit as a credit, leaving the remaining balance due. This presentation preserves the economic history. Simply invoicing only the unpaid remainder can make revenue reconciliation and customer understanding harder, particularly when a project has several milestones or change orders.',
        'Retainers require care because the accounting treatment can depend on whether the amount is earned immediately or held for future work. The invoice calculator can subtract a prior payment from the balance due, but it does not determine revenue recognition. Maintain records connecting each credit to the original payment, credit memo, refund, or adjustment so the customer ledger can be reconciled later.'
      ]},
      { heading: 'Payment terms should use an exact due date', paragraphs: [
        'Terms such as Net 15 or Net 30 are common, but an invoice is clearer when it also prints the actual due date. This avoids disagreement about whether the count begins on the invoice date, delivery date, or receipt date. State accepted payment methods and include the information the customer needs to pay, such as a payment link, ACH instructions delivered securely, or the correct remittance address.',
        'Match terms to the commercial relationship. A new client, custom project, or large material purchase may justify a deposit or milestone billing. A long-standing business customer may expect net terms. Faster terms improve working capital only if customers accept and follow them, so consider the sales process as well as the mathematical due date. A contract signed before work begins is the best place to establish these expectations.'
      ]},
      { heading: 'Late fees require both correct math and enforceable terms', paragraphs: [
        'A late fee can be a flat charge, periodic percentage, or interest-like amount depending on the agreement and applicable law. If the policy is 1.5% per month, define whether it applies to the overdue principal only, whether it compounds, and how partial months are handled. A calculator may prorate by days, but your contract should use the same method. Inconsistent calculation can create disputes larger than the fee itself.',
        'Do not add a late fee merely because a generic template recommends one. State law, industry rules, customer type, and the original agreement can affect what is permitted. The policy should generally be disclosed before the invoice becomes overdue. For an important delinquent account, preserving the customer relationship and collecting the principal may be more valuable than mechanically maximizing penalties.'
      ]},
      { heading: 'Worked invoice example with several moving parts', paragraphs: [
        'Assume a consultant bills 18 hours at $150, adds a $600 fixed deliverable, and has $150 of approved reimbursable expenses. The pre-discount subtotal is $3,450. A negotiated 5% discount on professional services should be applied according to the agreement, not automatically to reimbursable expenses. If only some lines are taxable, build the taxable subtotal after determining which discounted amounts belong in that base.',
        'Now subtract a $1,000 deposit already received and add any valid tax. The final invoice should display each stage so the client can reproduce the balance. If the client later pays only part of the amount, record that payment against the invoice rather than editing the original total. Preserving the original invoice and subsequent payment history gives you a clean accounts-receivable trail.'
      ]},
      { heading: 'Invoice numbering and records matter beyond appearance', paragraphs: [
        'Use a unique, consistent invoice number. Sequential numbering makes it easier to locate documents, reconcile payments, identify missing records, and communicate with customers. Include seller and customer legal names where appropriate, invoice date, due date, currency, purchase-order reference if required, and enough contact information to resolve billing questions. Some customers will reject invoices that omit their internal PO or vendor information.',
        'Keep copies of issued invoices and avoid silently overwriting a finalized invoice after it has been sent. If a correction is required, follow your accounting process with a revised invoice, void, or credit memo so the history remains understandable. Good records support bookkeeping, tax reporting, cash-flow forecasting, and collection efforts. The calculator produces totals; your invoicing workflow preserves evidence.'
      ]},
      { heading: 'Use the calculator to manage cash flow, not only arithmetic', paragraphs: [
        'Track days between invoice issuance, due date, and actual payment. If customers routinely pay fifteen days after Net 30, your real collection cycle is closer to forty-five days. That gap affects how much working capital the business needs for payroll, software, materials, and taxes. Faster invoicing after work is completed can improve cash flow without changing prices or payment terms.',
        'Before sending a large invoice, compare the calculated total with the contract, approved scope changes, prior deposits, and tax treatment. Then proofread the payment instructions. A mathematically perfect invoice sent to the wrong contact or bank account still does not get paid. Treat the calculator as one control in a broader billing process that includes agreement, documentation, delivery, follow-up, and reconciliation.'
      ]},
    ],
  },
  'fica-tax-calculator': {
    title: 'FICA Taxes Explained: Social Security, Medicare, and Payroll Planning',
    dek: 'FICA is not one flat tax applied identically to every dollar of income. Social Security has an annual wage base, Medicare generally does not, Additional Medicare Tax uses separate thresholds, and self-employment tax follows a related but different calculation. Accurate estimates begin by identifying the type and amount of earned income.',
    sections: [
      { heading: 'What FICA actually funds and who pays it', paragraphs: [
        'For employees, FICA withholding combines Social Security tax and Medicare tax. The employee pays a statutory share through payroll withholding and the employer generally pays a matching share. These payroll taxes are separate from federal income tax withholding. A paycheck can therefore show federal income tax, Social Security, Medicare, state tax, benefits, and retirement deductions as distinct lines even though they all reduce take-home pay.',
        'The Social Security portion is generally subject to an annual wage base, while the regular Medicare portion applies without the same wage ceiling. Because the rules differ, a calculator should compute the two components separately. Someone earning above the Social Security wage base can see Social Security withholding stop later in the year while Medicare withholding continues.'
      ]},
      { heading: 'The Social Security wage base is annual, not per job', paragraphs: [
        'The wage base applies to an individual’s covered wages for the year. With one employer, payroll systems normally stop employee Social Security withholding once that employer’s wages reach the annual limit. With multiple employers, each employer may withhold based only on the wages it pays because it does not necessarily know what another employer paid. That can result in excess employee Social Security tax being withheld during the year.',
        'When that happens, the federal income tax return may provide a mechanism to claim credit for excess employee withholding, subject to the applicable rules. The employer portions are a different matter. This is one reason a person with two high-paying jobs can see paycheck withholding that differs from a simple annual calculator. Use the calculator for planning, then reconcile actual Forms W-2 and tax documents when filing.'
      ]},
      { heading: 'Medicare tax and Additional Medicare Tax use different thresholds', paragraphs: [
        'Regular Medicare tax generally continues across covered wages rather than stopping at the Social Security wage base. Additional Medicare Tax can apply above a statutory threshold. Payroll withholding for the additional tax and the final tax liability can diverge because employer withholding rules may use a wage threshold that does not fully account for the employee’s filing status or a spouse’s wages.',
        'For example, two spouses can each earn below an employer withholding trigger while their combined wages exceed the threshold applicable to their joint return. The reverse can also occur for an individual whose employer withholds additional tax based on that employer’s wages but whose final filing-status calculation produces a different liability. A payroll estimate should therefore distinguish amount withheld from final tax owed.'
      ]},
      { heading: 'Self-employment tax is related to FICA but not identical', paragraphs: [
        'A sole proprietor or independent contractor does not have an employer withholding the employee half and separately paying an employer half. Instead, net earnings from self-employment can be subject to self-employment tax, which is designed to cover both Social Security and Medicare components. The calculation uses net earnings rather than simply applying the combined rate to gross business receipts.',
        'Business revenue must first be reduced by legitimate deductible business expenses to determine net profit, and the self-employment tax computation then applies its statutory adjustment and limits. A portion of self-employment tax may also be deductible for income-tax purposes. Because income tax and self-employment tax interact, a contractor should not treat the FICA-style result as the entire tax bill.'
      ]},
      { heading: 'Worked employee example across the wage base', paragraphs: [
        'Consider an employee whose annual wages are below the Social Security wage base. Social Security withholding is calculated on all covered wages, and regular Medicare withholding is also calculated on those wages. If earnings later rise above the Social Security limit, only the wages up to that annual cap are subject to the employee Social Security component, while Medicare continues according to its rules.',
        'This creates a visible change in take-home pay for some high earners late in the year. Once Social Security withholding stops, net pay can increase even though salary is unchanged. That temporary increase should not automatically be treated as a permanent raise because withholding typically resumes with the first paycheck of the next calendar year when the annual wage-base calculation resets.'
      ]},
      { heading: 'Bonuses and supplemental wages can make a paycheck look surprising', paragraphs: [
        'A bonus may use a different federal income-tax withholding method, but covered supplemental wages are still generally relevant to Social Security and Medicare taxes. Employees sometimes interpret a heavily withheld bonus as being taxed at a permanently higher income-tax rate when part of the reduction is payroll tax and part is merely the withholding method. Final federal income tax is reconciled on the annual return.',
        'When estimating the net amount of a bonus, include the remaining Social Security wage-base room for the year. If regular wages have already reached the annual cap before the bonus is paid, the Social Security component can differ from an earlier-year bonus. Medicare and potentially Additional Medicare Tax still need separate consideration.'
      ]},
      { heading: 'Pre-tax benefits do not all reduce FICA wages the same way', paragraphs: [
        'A deduction labeled pre-tax does not necessarily mean it is excluded from every tax base. Certain health-plan or cafeteria-plan deductions can reduce wages subject to federal income tax and FICA, while traditional 401(k) deferrals generally reduce federal taxable income but remain subject to Social Security and Medicare taxes. The exact treatment depends on the benefit and plan rules.',
        'For paycheck reconciliation, compare gross pay with the Social Security wages and Medicare wages reported on the pay stub or year-end Form W-2. Differences can reveal how benefits are treated. Do not subtract every pre-tax deduction from wages before using a FICA calculator unless you know that deduction is excluded from the relevant payroll-tax base.'
      ]},
      { heading: 'Employer payroll cost is higher than the employee’s salary', paragraphs: [
        'For a business budgeting a hire, gross salary is only one component of compensation cost. The employer generally owes its share of Social Security and Medicare taxes in addition to wages, and may also have federal and state unemployment taxes, workers’ compensation, benefits, payroll-service fees, and other costs. An employee FICA calculator should not be mistaken for a complete employer burden calculator.',
        'This distinction is also useful when comparing employee and contractor arrangements. A contractor’s quoted rate may be higher partly because the contractor handles self-employment tax, benefits, unpaid time, equipment, insurance, and administrative costs. Worker classification is a legal question based on the actual relationship; it cannot be chosen solely to reduce payroll taxes.'
      ]},
      { heading: 'How to use a FICA estimate responsibly', paragraphs: [
        'Enter covered wages for the correct calendar year and verify the wage base and thresholds used by the calculator. If you have multiple jobs, self-employment income, household wages near an Additional Medicare threshold, or unusual benefits, run separate scenarios rather than assuming one simple percentage will match every paycheck. Compare estimated annual amounts with year-to-date payroll withholding to identify large differences early.',
        'Tax parameters can change by year, and official guidance controls. A calculator is useful for budgeting take-home pay, understanding payroll lines, and estimating employer or self-employment costs, but it is not a substitute for current IRS instructions or professional advice in a complex case. Always verify year-specific limits before relying on a result for filing or payroll decisions.'
      ]},
    ],
  },
  'annual-income-calculator': {
    title: 'From Hourly Pay to Real Annual Income: A Complete Conversion Guide',
    dek: 'Annualizing pay is easy only when hours, weeks, and rates never change. Real compensation can include overtime, unpaid time off, bonuses, commissions, multiple jobs, and benefits. The most useful annual-income estimate separates guaranteed base earnings from variable compensation and from take-home pay.',
    sections: [
      { heading: 'The basic hourly-to-annual formula and its assumptions', paragraphs: [
        'The familiar full-time conversion multiplies hourly rate by 40 hours per week and 52 weeks, producing 2,080 paid hours per year. It is a convenient benchmark, not a universal truth. It assumes every week is paid and the employee works exactly forty paid hours. Unpaid vacation, seasonal shutdowns, variable schedules, or part-time work can make actual annual earnings materially lower.',
        'For a more accurate estimate, multiply the expected paid hours per week by the number of paid weeks. Someone working 32 hours for 50 paid weeks has 1,600 annual paid hours, not 2,080. If hours fluctuate, use a conservative average from recent pay stubs or scheduling history. Separate predictable base hours from overtime so the estimate does not depend on unusually busy periods continuing forever.'
      ]},
      { heading: 'Salary conversions should distinguish pay frequency from earnings', paragraphs: [
        'A $72,000 annual salary can be expressed as $6,000 per month, $3,000 semimonthly, about $2,769.23 biweekly, or about $1,384.62 weekly before deductions, depending on the payroll schedule. Biweekly and semimonthly are not the same: biweekly normally produces 26 paychecks per year, while semimonthly produces 24. Confusing the two can create an incorrect monthly budget.',
        'The annual salary is the economic starting point, while each paycheck reflects the employer’s payroll calendar. Some years can contain an extra weekly or biweekly payday depending on dates and payroll practice. For budgeting, use the actual pay schedule from your employer rather than assuming every month receives exactly two checks.'
      ]},
      { heading: 'Overtime can materially change annual income', paragraphs: [
        'For a nonexempt employee eligible for overtime, hours above the applicable threshold may be paid at a premium rate, commonly one and one-half times the regular rate under federal rules, with state rules potentially adding requirements. An annual calculator should therefore separate regular hours from overtime hours rather than multiplying every hour by the base rate.',
        'Suppose an employee earns $24 per hour, normally works 40 regular hours and averages five overtime hours each week for 48 working weeks. Base earnings and overtime earnings should be calculated separately. But if overtime depends on seasonal demand, model a low, expected, and high case. Building fixed household commitments around the high case can create problems when overtime disappears.'
      ]},
      { heading: 'Bonuses and commissions belong in a variable-income layer', paragraphs: [
        'A target bonus is not the same as guaranteed salary. Sales commissions can depend on quota attainment, customer payment, territory, product mix, or company rules. When evaluating a job offer, calculate guaranteed annual cash compensation first, then add a conservative estimate of variable compensation. If the employer provides historical attainment data, use it to test whether the stated on-target earnings are realistic.',
        'For personal budgeting, consider using only base income for essential recurring expenses and directing variable income toward taxes, savings, debt, or discretionary goals. This reduces lifestyle pressure during weak commission periods. The calculator can show total expected annual income, but labeling each component as guaranteed or variable makes the number far more useful.'
      ]},
      { heading: 'Gross annual income is not take-home income', paragraphs: [
        'Gross income is compensation before payroll deductions. Net pay depends on federal income-tax withholding, Social Security and Medicare taxes, state and local taxes where applicable, health premiums, retirement contributions, HSA or FSA elections, garnishments, and other deductions. A single flat tax percentage is therefore only a rough planning shortcut.',
        'Tax brackets are marginal, which means moving into a higher bracket does not generally cause all income to be taxed at the higher rate. Withholding also is not identical to final tax liability. If you need a precise take-home estimate, use year-specific payroll rules and your filing information. Keep the annual-income conversion focused on gross earnings unless the calculator explicitly models taxes and benefits.'
      ]},
      { heading: 'Paid time off changes the value of an hourly offer', paragraphs: [
        'Two jobs offering the same hourly rate can produce different annual value if one pays holidays and vacation while the other does not. An hourly worker paid for 52 weeks can earn more than a contractor who takes four unpaid weeks even at the same nominal rate. When comparing offers, calculate expected paid hours and separately value employer-paid time that replaces hours you otherwise would need to work.',
        'For contractors, also account for nonbillable time. Forty hours spent working in a week does not necessarily mean forty billable hours; sales, administration, bookkeeping, training, and proposal work can consume time without direct client revenue. Converting a desired annual income into a freelance hourly rate therefore requires fewer billable hours and additional allowance for business expenses and taxes.'
      ]},
      { heading: 'Total compensation can be more important than salary alone', paragraphs: [
        'Employer retirement contributions, health insurance subsidies, HSA funding, equity awards, pension accruals, paid leave, education benefits, and other compensation can materially change the value of a job. A higher salary with expensive health coverage may not dominate a slightly lower salary with strong employer-paid benefits. Build a separate total-compensation comparison rather than forcing every benefit into the annual wage number.',
        'Equity deserves special caution because its future value is uncertain and vesting conditions matter. A grant stated at today’s value is not equivalent to cash salary. Likewise, an employer match is valuable only to the extent you meet the plan conditions. Annual income should describe cash earnings; total compensation should layer in benefits with clear assumptions.'
      ]},
      { heading: 'Worked comparison: hourly offer versus salary offer', paragraphs: [
        'Imagine an hourly role pays $31 with 40 expected hours, two unpaid weeks, and occasional overtime, while a salary role pays $64,000 with paid vacation and a retirement match. The simple 2,080-hour conversion makes the hourly rate look like $64,480, almost identical to salary. Adjusting for two unpaid weeks reduces base hourly earnings before overtime, and the salary benefits can widen the difference.',
        'Now add realistic overtime rather than maximum overtime, then subtract any employee benefit-cost differences. The better offer may still be the hourly role, but the conclusion is based on expected annual economics rather than one multiplication. Also compare schedule control, commute, job stability, advancement, and the risk that overtime is reduced. Compensation is a major input to a career decision, not the entire decision.'
      ]},
      { heading: 'Use several annual-income scenarios when earnings vary', paragraphs: [
        'For hourly, commission, freelance, or seasonal work, calculate a floor, expected case, and strong year. The floor should use hours and variable pay that you could reasonably expect during a weak period. Use that number for essential budgeting and debt affordability. The expected case can guide normal saving goals, while the strong case shows potential upside without turning it into a permanent spending commitment.',
        'Revisit the estimate after major changes in rate, schedule, overtime policy, or job status. Compare the annualized projection with year-to-date earnings on your pay stub. If the projection consistently exceeds actual earnings, reduce the assumed hours or variable pay. A good annual-income calculator is not merely a converter; it is a forecasting tool whose assumptions should be checked against reality.'
      ]},
    ],
  },
}

const supplements: Record<string, { heading: string; paragraphs: string[] }> = {
  'weekly-budget-calculator': { heading: 'Advanced weekly-budget checks before you change the plan', paragraphs: [
    'Check timing as well as totals. A week can look affordable on paper while still causing an overdraft if a large automatic payment clears before the paycheck. Keep a calendar of major withdrawals and maintain a checking buffer that is separate from the amount available for discretionary spending. If your employer pays every other Friday, map at least the next six paydays against rent, mortgage, card due dates, insurance, and other automatic drafts. Cash-flow timing is a different problem from whether annual income exceeds annual expenses, and a useful weekly system needs to handle both.',
    'Distinguish true savings from money reserved for known spending. If you transfer $100 per week into a vacation fund, that is progress toward a goal but it is not the same as retirement investing or building permanent net worth once the vacation is taken. Tracking separate buckets—emergency reserve, sinking funds, debt reduction, and long-term investment—makes the savings-rate result easier to interpret. The same principle applies to credit cards: purchases should be recorded when made, not only when the card bill is paid, otherwise one week can appear artificially cheap and the payment week artificially expensive.',
    'Finally, test the plan against a bad but plausible week. Add a higher grocery bill, an extra tank of fuel, a copay, and a small household replacement. If that immediately forces debt, the budget may be too tight even if the normal-week arithmetic balances. A resilient plan leaves room for ordinary volatility. The objective is not to predict every dollar perfectly; it is to create enough margin that routine surprises do not repeatedly become financial emergencies.'
  ]},
  'savings-rate-calculator': { heading: 'Advanced interpretation: taxes, debt, and goal-specific savings', paragraphs: [
    'Tax-advantaged contributions complicate a take-home calculation because a traditional 401(k), HSA, or similar payroll deduction can reduce both the cash that reaches your bank and current taxable wages. Decide whether to reconstruct income before those contributions or to use bank-deposit income and add only savings funded from that cash. Mixing methods can double count a payroll contribution. A simple reconciliation is to start from a pay stub, identify gross compensation, taxes, benefit premiums, and retirement contributions, then write down exactly which lines your chosen savings-rate definition includes.',
    'Debt principal deserves its own dashboard even if you decide not to count it as savings. Paying $500 of extra mortgage principal and investing $500 both increase net worth by roughly $500 at the moment of payment, but they create different liquidity, risk, and expected-return profiles. Paying down a credit card at a very high interest rate can have a strong guaranteed economic benefit, while extra low-rate mortgage principal may be less urgent for someone who needs liquid reserves. A single percentage cannot express those differences, so pair savings rate with debt balances and emergency-fund coverage.',
    'Goal-specific rates can also be more actionable than one household-wide number. You might track retirement saving as a percentage of gross pay, short-term goal saving as a percentage of take-home pay, and total net-worth additions as a percentage of total compensation. This sounds more complex, but each metric answers a distinct question. The calculator can provide the headline number; your financial plan should explain what the saved dollars are expected to accomplish and when they may be needed.'
  ]},
  'qualified-dividend-tax-calculator': { heading: 'Planning questions that change the after-tax dividend result', paragraphs: [
    'Ask whether the dividend is being evaluated in isolation or as part of a larger transaction year. A business sale, large stock gain, Roth conversion, severance payment, or unusually large bonus can change taxable income enough to alter the rate applied to preferential income. Charitable deductions, capital-loss carryforwards, and other items can also affect the final return. For planning, model the dividend with and without the unusual event rather than assuming last year’s effective tax rate will repeat.',
    'Consider the economic effect of dividend reinvestment. Reinvesting does not generally make a taxable-account dividend disappear for federal tax purposes; the cash distribution can still be taxable even though it immediately buys more shares. Each reinvestment creates a new tax lot with its own basis and acquisition date. Over many years, accurate lot records matter for both the qualified-dividend holding period and the gain or loss when shares are eventually sold. Automatic reinvestment is convenient, but it increases recordkeeping detail.',
    'For portfolio comparisons, focus on after-tax total return rather than dividend yield alone. A company that retains earnings and grows share value may create return primarily as unrealized appreciation, while a mature company may distribute more cash currently. The tax timing can differ, but so can business risk and expected return. A dividend-tax calculator helps quantify one tax component; it should not be used to rank investments without considering price changes, diversification, fees, and the investor’s broader tax situation.'
  ]},
  'margin-trading-calculator': { heading: 'Stress tests to run before borrowing against securities', paragraphs: [
    'Run more than one downside scenario. A 10% decline is not a severe stress test for an individual stock, sector fund, or volatile market. Calculate what happens at 20%, 30%, and 40% declines, then add accrued interest and a higher maintenance requirement. If any of those scenarios would force a sale, decide whether the position size is acceptable before entering it. Historical drawdowns show that markets can move farther and faster than an investor expects, especially when liquidity is poor.',
    'Separate trading capital from money needed for taxes, rent, tuition, emergencies, or near-term purchases. A margin account can create pressure to add cash precisely when markets are falling. If the only available cash is also your emergency fund, a market decline can turn investment risk into household cash-flow risk. Keeping unrelated reserves outside the leveraged strategy reduces the chance that a temporary market move forces a damaging personal-finance decision.',
    'Also model the opportunity cost of interest. If the expected return advantage of leverage is only a few percentage points above the borrowing rate, a modest market shortfall can eliminate the benefit. Interest rates can change while the investment thesis remains unchanged. The relevant comparison is not “did the stock go up?” but “did the leveraged position outperform the same unleveraged investment after financing cost, taxes, fees, and the additional risk of forced liquidation?”'
  ]},
  'rental-property-depreciation-calculator': { heading: 'Ownership changes and edge cases that can alter the schedule', paragraphs: [
    'A property converted from personal use to rental use can require a basis determination different from a property purchased directly as an investment. Likewise, a property inherited, received by gift, partially used as a residence, or used for short-term rental may involve additional rules. Do not assume the original purchase price is always the correct starting basis. Document how and when the property entered rental service and whether any portion remained personal.',
    'Periods of vacancy also require context. A rental can generally remain in service while temporarily vacant if it is held out and available for rent, but a property removed from the rental market for substantial personal use or conversion may be treated differently. Improvements completed during vacancy can have separate placed-in-service dates. Keep listings, leases, renovation invoices, and records showing when the unit was actually available to tenants; these facts can support the depreciation timeline years later.',
    'When evaluating a purchase, do not let the depreciation deduction rescue an otherwise weak investment. Start with rent, realistic vacancy, maintenance, capital expenditures, insurance, taxes, management, financing, and expected long-term demand. Then layer tax effects onto the economic return. Depreciation can improve after-tax cash flow, but it does not repair negative operating economics, eliminate sale taxes, or guarantee appreciation. The strongest analysis works before tax and after tax.'
  ]}
}

export function CalculatorDeepDive({ slug }: { slug: string }) {
  const guide = guides[slug]
  if (!guide) return null
  return (
    <article className="mt-8 rounded-2xl border border-gray-100 bg-white p-5 sm:p-7 text-gray-700">
      <h2 className="text-2xl font-black text-gray-900 mb-3">{guide.title}</h2>
      <p className="text-sm sm:text-base leading-7 mb-7">{guide.dek}</p>
      <div className="space-y-8">
        {guide.sections.map((section) => (
          <section key={section.heading}>
            <h3 className="text-lg font-bold text-gray-900 mb-3">{section.heading}</h3>
            <div className="space-y-3">
              {section.paragraphs.map((p, i) => <p key={i} className="text-sm sm:text-base leading-7">{p}</p>)}
            </div>
            {section.bullets && <ul className="mt-3 list-disc pl-6 space-y-2">{section.bullets.map((b) => <li key={b}>{b}</li>)}</ul>}
          </section>
        ))}
      </div>
      {supplements[slug] && (
        <section className="mt-8 border-t border-gray-100 pt-7">
          <h3 className="text-lg font-bold text-gray-900 mb-3">{supplements[slug].heading}</h3>
          <div className="space-y-3">{supplements[slug].paragraphs.map((p, i) => <p key={i} className="text-sm sm:text-base leading-7">{p}</p>)}</div>
        </section>
      )}
    </article>
  )
}
